class WeatherSystem:
    CELSIUS = 'celsius'
    FAHRENHEIT = 'fahrenheit'

    def __init__(self, city) -> None:
        self._temperature = None
        self._weather = None
        self._city = city
        self._weather_list = {}

    @property
    def temperature(self):
        return self._temperature

    @temperature.setter
    def temperature(self, value):
        self._temperature = value

    @property
    def weather(self):
        return self._weather

    @weather.setter
    def weather(self, value):
        self._weather = value

    @property
    def city(self):
        return self._city

    @city.setter
    def city(self, value):
        self._city = value

    @property
    def weather_list(self):
        return self._weather_list

    @weather_list.setter
    def weather_list(self, value):
        self._weather_list = value

    def query(self, weather_dict, tmp_units=CELSIUS):
        self._weather_list = weather_dict
        if self.city not in weather_dict:
            return False

        temperature = self._get_temperature_for_city()
        weather = self._get_weather_for_city()

        self.temperature = temperature
        self.weather = weather

        if self._needs_conversion(tmp_units):
            return self._convert_temperature(tmp_units), weather

        return temperature, weather

    def _get_temperature_for_city(self):
        return self.weather_list[self.city]['temperature']

    def _get_weather_for_city(self):
        return self.weather_list[self.city]['weather']

    def _needs_conversion(self, unit):
        return self.weather_list[self.city]['temperature units'] != unit

    def _convert_temperature(self, target_unit):
        if target_unit == CELSIUS:
            return self.fahrenheit_to_celsius()
        elif target_unit == FAHRENHEIT:
            return self.celsius_to_fahrenheit()
        return self.temperature

    def set_city(self, city):
        self.city = city

    def celsius_to_fahrenheit(self):
        return (self.temperature * 9/5) + 32

    def fahrenheit_to_celsius(self):
        return (self.temperature - 32) * 5/9
